Translate("ptBR", "wetlands", {
	title = "Pantanal",
	aliases = { "O Pantanal" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Pantanal é uma vasta terra de charcos, juncos e águas negras e lentas, ao norte das montanhas de Khaz Modan. A névoa paira sobre ela durante boa parte do ano. Uma grande estrada a atravessa: sobe de {link:dun-algaz}Dun Algaz{/link} ao sul, segue para o norte passando pelas ruínas de antigas fortalezas anãs e termina na {link:thandol-span}Ponte Thandol{/link}, a ponte que une as terras dos anões aos reinos humanos do norte. Uma segunda estrada vira para oeste, rumo ao mar, onde o {link:menethil-harbor}Porto de Menethil{/link} mantém a vigília da {link:alliance}Aliança{/link} sobre a costa. Sempre foi uma terra dura, rica em crocoliscos e raptores e pobre em conforto. Agora é também uma terra em guerra.]=],
		},
		{
			title = "Origens",
			text = [=[Nenhuma crônica registra quem ergueu as primeiras pedras nestes pântanos. Os anões os reivindicam há muitos séculos. No leste ergue-se a fortaleza montanhesa de {link:grim-batol}Grim Batol{/link}, outrora sede do clã Martelo Feroz. Na Guerra dos Três Martelos, os {link:dark-iron-dwarves}Ferro Negro{/link} atacaram Grim Batol, e a feitiçaria sombria ali liberada deixou a fortaleza maculada. Os Martelo Feroz a abandonaram e partiram para o norte, para os picos das {link:the-hinterlands}Terras Agrestes{/link}. A {link:explorers-league}Liga dos Exploradores{/link} ainda encontra coisas mais antigas sob a lama: ossos de grandes feras e pedras gravadas numa escrita que nenhum {link:dwarves}anão{/link} escreveu.]=],
		},
		{
			title = "Os Dias Atuais",
			text = [=[O {link:menethil-harbor}Porto de Menethil{/link} guarda a costa oeste para a {link:alliance}Aliança{/link}, sob os anões do {link:kingdom-of-ironforge}Reino de Altaforja{/link}. Além de suas muralhas, o Pantanal está se desfazendo. Sabotadores {link:dark-iron-dwarves}Ferro Negro{/link} destruíram a {link:thandol-span}Ponte Thandol{/link} e tomaram {link:dun-modr}Dun Modr{/link}, e os sobreviventes do regimento que os guardava esperam nas ruínas por uma reserva que nunca chega. Os {link:dragonmaw-clan}orcs Presa do Dragão{/link}, derrotados e dispersos depois da {link:second-war}Segunda Guerra{/link}, encontraram um novo chefe e um novo acampamento. Avançaram sobre {link:dun-algaz}Dun Algaz{/link} e ameaçam isolar Menethil de {link:loch-modan}Loch Modan{/link}. No {link:whelgar-s-excavation-site}Sítio de Escavação de Whelgar{/link}, raptores mataram a maior parte de uma equipe da {link:explorers-league}Liga dos Exploradores{/link}. Acima dessa escavação, a névoa começou a descer das montanhas, luzes piscam nas alturas e construtos de pedra caminham onde ninguém caminha há eras. A única notícia de esperança vem pelo mar: novos navios agora partem de Menethil para {link:southshore}Costa Sul{/link} e seguem até {link:auberdine}Auberdine{/link}.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}Os anões de {link:ironforge}Altaforja{/link}.{/b} Soldados, mineiros, sacerdotes e estudiosos guardam o {link:menethil-harbor}Porto de Menethil{/link}, o acampamento diante de {link:dun-modr}Dun Modr{/link} e a escavação da {link:explorers-league}Liga dos Exploradores{/link}.
• {b}O povo de Menethil.{/b} {link:humans}Humanos{/link} dos antigos reinos trabalham nas docas, tabernas e curtumes ao lado dos anões.
• {b}O {link:dragonmaw-clan}clã Presa do Dragão{/link}.{/b} {link:orcs}Orcs{/link} que outrora montavam dragões vermelhos na guerra, agora acampados nas colinas a leste da estrada.
• {b}Os {link:dark-iron-dwarves}Ferro Negro{/link}.{/b} Seus sabotadores, escavadores e bruxos dominam Dun Modr e o {link:direforge-hill}Monte Umbraforja{/link}.
• {b}Os gnolls Pelemusgo.{/b} Um clã de {link:gnolls}gnolls{/link} dos charcos, numeroso demais para a terra que o alimenta.
• {b}Os murlocs Peixeazul.{/b} {link:murlocs}Murlocs{/link} que saqueiam a costa e os navios mercantes que passam por ela.
• {b}Os mortos afogados.{/b} Marinheiros amaldiçoados ainda caminham pelos destroços da {link:the-lost-fleet}Frota Perdida{/link}, na costa noroeste.]=],
		},
		{
			title = "História",
			text = [=[• {b}Os Três Martelos.{/b} {link:grim-batol}Grim Batol{/link} silenciou depois da guerra dos três clãs, e os Martelo Feroz deixaram o Pantanal para trás.
• {b}A {link:second-war}Segunda Guerra{/link}.{/b} A {link:horde}Horda{/link} invadiu Khaz Modan. O {link:dragonmaw-clan}clã Presa do Dragão{/link} fez de Grim Batol sua fortaleza, e os orcs construíram um porto na costa oeste para atacar {link:hillsbrad-foothills}Eira dos Montes{/link} pelo mar. {link:the-drag}Drag{/link}ões vermelhos sob comando {link:orcs}orc{/link} queimaram a {link:third-fleet}Terceira Frota{/link} de {link:kul-tiras}Kul Tiraz{/link} diante destas costas.
• {b}Menethil.{/b} O Almirante {link:daelin-proudmoore}Daelin Proudmoore{/link} expulsou os orcs de seu porto, e a {link:alliance}Aliança{/link} ergueu um porto próprio no mesmo lugar, batizado em honra do Rei {link:terenas-menethil}Terenas Menethil{/link}.
• {b}Os Dias Atuais.{/b} Os {link:dark-iron-dwarves}Ferro Negro{/link} se ergueram no norte, os Presa do Dragão voltaram no leste, e as reservas de {link:ironforge}Altaforja{/link} foram enviadas para lutar em outras frentes.]=],
		},
		{
			title = "Lendas do Pantanal",
			text = [=[• As peles de crocolisco do curtume de Menethil são vendidas em portos do mundo inteiro.
• Um espírito do pântano, chamado {link:rethiel-the-greenwarden}Guarda Verde{/link}, caminha entre os crocoliscos a leste da bifurcação para {link:dun-modr}Dun Modr{/link}. Quem o procura ouve que não vai voltar.
• Os gnolls Pelemusgo queimam árvores vivas para se aquecer, e o Guarda Verde não os perdoou.
• O último sobrevivente da {link:third-fleet}Terceira Frota{/link} diz que, em seus sonhos, ainda ouve os gemidos de seus irmãos afogados.]=],
		},
	},
})

Translate("ptBR", "menethil-harbor", {
	title = "Porto de Menethil",
	sections = {
		{
			title = "Resumo",
			text = [=[O Porto de Menethil é o porto da {link:alliance}Aliança{/link} na costa oeste do {link:wetlands}Pantanal{/link}. Ergue-se no lugar onde a {link:horde}Horda{/link} outrora construiu navios para a {link:second-war}Segunda Guerra{/link}, e muito da madeira e do ferro que ela roubou de Khaz Modan ainda está espalhado por suas docas. Sua fortaleza leva o nome do Rei {link:terenas-menethil}Terenas Menethil{/link}. Os anões de {link:ironforge}Altaforja{/link} o comandam, e o {link:captain-stoutfist}Capitão Stoutfist{/link} planeja sua defesa na sala de guerra da Bastilha Menethil. Navios partem de seus píeres para {link:auberdine}Auberdine{/link}, para {link:theramore-isle}Theramore{/link}, do outro lado do mar, e agora também para {link:southshore}Costa Sul{/link}. Na Taberna Aguafunda, marinheiros, estudiosos, espiões e um sobrevivente bêbado da {link:third-fleet}Terceira Frota{/link} dividem as mesmas mesas.]=],
		},
	},
})

Translate("ptBR", "dun-modr", {
	title = "Dun Modr",
	sections = {
		{
			title = "Resumo",
			text = [=[Dun Modr é uma cidade anã no norte do {link:wetlands}Pantanal{/link}, na estrada para a {link:thandol-span}Ponte Thandol{/link}. Um regimento de {link:ironforge}Altaforja{/link} guardava a cidade e a ponte mais adiante. Os {link:dark-iron-dwarves}Ferro Negro{/link} atacaram primeiro a ponte e depois caíram sobre a cidade antes que o regimento pudesse se reorganizar, e a maioria dos anões foi morta. {link:longbraid-the-grim}Longbraid, o Severo{/link}, tocou a retirada. O que resta de seu regimento acampa agora logo além das muralhas, enquanto soldados, escavadores e demolidores Ferro Negro dominam as ruas. Uma criatura de fogo foi vista acorrentada entre eles, e um elemental chamado Modr caminha pelas ruínas.]=],
		},
	},
})

Translate("ptBR", "thandol-span", {
	title = "Ponte Thandol",
	aliases = { "A Ponte Thandol" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Ponte Thandol é a grande ponte na borda norte do {link:wetlands}Pantanal{/link}. Ela cruza um desfiladeiro profundo até o {link:arathi-highlands}Planalto Arathi{/link} e leva a estrada principal entre Khaz Modan e as terras do norte. Os {link:dark-iron-dwarves}Ferro Negro{/link} explodiram sua ponte oeste numa emboscada, e muitos anões morreram com ela, entre eles o irmão de {link:longbraid-the-grim}Longbraid, o Severo{/link}. O plano foi traçado por um Ferro Negro chamado {link:kam-deepfury}Kam Deepfury{/link}. Seus agentes esconderam mais explosivos do outro lado do desfiladeiro para derrubar o que restava. Se a Ponte cair, os anões perdem sua principal linha de suprimentos para o norte.]=],
		},
	},
})

Translate("ptBR", "whelgar-s-excavation-site", {
	title = "Sítio de Escavação de Whelgar",
	aliases = { "Escavação de Whelgar" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Sítio de Escavação de Whelgar é uma escavação da {link:explorers-league}Liga dos Exploradores{/link} no meio do {link:wetlands}Pantanal{/link}. A equipe do {link:prospector-whelgar}Prospector Whelgar{/link} desenterrava relíquias antigas quando começou a encontrar ossos enormes. Logo depois, os raptores malhados do pântano varreram o lugar. Muitos escavadores morreram. Três sobreviventes resistem num penhasco acima das ruínas de seu acampamento. Entre os achados há uma tábua quebrada, gravada na escrita dos titãs: a {link:goaz-stone}Pedra de Goaz{/link}. Mais acima, nas colinas a sudeste, além da antiga escavação, fica um segundo acampamento que a Liga abriu, e dele um caminho leva ao {link:excavation-site}Sítio de Escavação{/link}.]=],
		},
	},
})

Translate("ptBR", "dun-algaz", {
	title = "Dun Algaz",
	sections = {
		{
			title = "Resumo",
			text = [=[Dun Algaz é o desfiladeiro entre {link:loch-modan}Loch Modan{/link} e o {link:wetlands}Pantanal{/link}, guardado em sua boca sul pelos anões da {link:algaz-station}Estação Algaz{/link}. É a única estrada pela qual os soldados de {link:ironforge}Altaforja{/link} podem chegar ao {link:menethil-harbor}Porto de Menethil{/link} por terra. Os {link:dragonmaw-clan}orcs Presa do Dragão{/link} sempre se mantiveram nas colinas, mas agora desceram ao desfiladeiro em grande número, liderados por um senhor da guerra chamado {link:ma-ruk-wyrmscale}Ma'ruk Wyrmscale{/link}. Ninguém em Menethil sabe dizer o que os levou a isso. Se eles tomarem Dun Algaz, o porto ficará sozinho.]=],
		},
	},
})

Translate("ptBR", "grim-batol", {
	title = "Grim Batol",
	sections = {
		{
			title = "Resumo",
			text = [=[Grim Batol é uma fortaleza montanhesa no extremo leste do {link:wetlands}Pantanal{/link}, atrás dos Portões {link:dragonmaw-clan}Presa do Dragão{/link}. Foi construída pelos anões Martelo Feroz, que a deixaram depois da Guerra dos Três Martelos, quando uma feitiçaria sombria corrompeu seus salões. Na {link:second-war}Segunda Guerra{/link}, o clã Presa do Dragão fez dela sua fortaleza. Ali mantiveram {link:alexstrasza}Alexstrasza{/link}, rainha dos dragões vermelhos, acorrentada pelo poder de um artefato criado por {link:deathwing}Asa da Morte{/link}, e criaram seus filhotes como montarias de guerra. A rainha já foi libertada. {link:the-drag}Drag{/link}ões vermelhos agora se reúnem diante dos portões de Grim Batol, e não toleram estranhos.]=],
		},
	},
})

Translate("ptBR", "angerfang-encampment", {
	title = "Acampamento Presirada",
	sections = {
		{
			title = "Resumo",
			text = [=[O Acampamento Presirada é o acampamento de guerra dos {link:dragonmaw-clan}orcs Presa do Dragão{/link}, nas colinas a leste da estrada do {link:wetlands}Pantanal{/link}. Depois da {link:second-war}Segunda Guerra{/link}, os poucos Presa do Dragão que sobreviveram à vingança dos dragões vermelhos fugiram de {link:grim-batol}Grim Batol{/link} e se esconderam nestas montanhas. Aqui, sob o {link:chieftain-nek-rosh}Chefe Nek'rosh{/link}, voltaram a ficar fortes. Seus estandartes de guerra tremulam sobre o acampamento, seus centuriões e guardiões das sombras treinam nele, e suas catapultas de cerco estão prontas para a marcha sobre o {link:menethil-harbor}Porto de Menethil{/link}.]=],
		},
	},
})

Translate("ptBR", "dragonmaw-retreat", {
	title = "Dragonmaw Retreat",
	sections = {
		{
			title = "Resumo",
			text = [=[Dragonmaw Retreat é um reduto escondido dos {link:dragonmaw-clan}orcs Presa do Dragão{/link} nas colinas do leste do {link:wetlands}Pantanal{/link}. Aqui o clã guarda armas para soldados que ainda não armou. Seus guerreiros não são apenas combatentes: vinculadores de almas e recuperadores andam entre eles, e ali foi visto um dragonete, curvado e subjugado. O {link:captain-stoutfist}Capitão Stoutfist{/link} ficaria feliz em ver esse arsenal levado embora antes que possa ser usado. O que os orcs pretendem recuperar, os anões só podem adivinhar.]=],
		},
	},
})

Translate("ptBR", "mosshide-fen", {
	title = "Charco Pelemusgo",
	sections = {
		{
			title = "Resumo",
			text = [=[O Charco Pelemusgo é um trecho de pântano no sul do {link:wetlands}Pantanal{/link}, perto do portão {link:dwarves}anão{/link} de Algaz. Seu nome vem dos gnolls Pelemusgo. Os gnolls viveram em paz nos charcos por muitos anos, mas seu número cresceu. Eles pisoteiam os arbustos e as flores do pântano, cortam suas árvores para suas fogueiras e carregam pederneiras toscas para acendê-las. O espírito chamado {link:rethiel-the-greenwarden}Guarda Verde{/link} os marcou como uma ferida na terra.]=],
		},
	},
})

Translate("ptBR", "sundown-marsh", {
	title = "Pântano do Ocaso",
	sections = {
		{
			title = "Resumo",
			text = [=[O Pântano do Ocaso fica no norte do {link:wetlands}Pantanal{/link}, uma terra baixa e úmida de poças e juncos. Os gnolls Pelemusgo também caçam aqui, com seus místicos e alfas entre eles. Coisas mais estranhas se erguem da água. Rastejantes do charco se arrastam pelos canais, e senhores do charco ainda maiores se erguem entre eles. {link:rethiel-the-greenwarden}O Guarda Verde{/link} os chama de bolhas febris na terra, nascidas de uma supuração que ninguém sabe explicar, e deseja devolvê-los ao pântano.]=],
		},
	},
})

Translate("ptBR", "saltspray-glen", {
	title = "Vale Espuma de Sal",
	sections = {
		{
			title = "Resumo",
			text = [=[O Vale Espuma de Sal é uma depressão no noroeste do {link:wetlands}Pantanal{/link}, aberta ao vento que vem do mar. É terra de raptores. Os raptores navalhadentes que caçam aqui recebem esse nome por seus dentes, longos e afiados o bastante para perfurar as escamas de um dragonete, e dizem que seus ovos têm gemas do tamanho da cabeça de um {link:gnomes}gnomo{/link}. O {link:dwarves}anão{/link} {link:howin-kindfeather}Howin Kindfeather{/link} manda caçadores aqui em busca de ambos.]=],
		},
	},
})

Translate("ptBR", "ironbeard-s-tomb", {
	title = "Tumba dos Barbaférreos",
	sections = {
		{
			title = "Resumo",
			text = [=[A Tumba dos Barbaférreos é um antigo local de sepultamento {link:dwarves}anão{/link} no norte do {link:wetlands}Pantanal{/link}, não muito longe de {link:dun-modr}Dun Modr{/link}. Quem quer que tenha sido Ironbeard, a tumba sobreviveu a seu nome. Gosmas carmesins gotejantes agora rastejam por ela e engolem o que tocam. Uma mulher de Menethil chamada {link:sida}Sida{/link} ainda vem até aqui uma vez por semana, com gosmas ou sem elas, e certa vez teve de fugir delas sem sua bolsa.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Nenhuma crônica diz quem foi Ironbeard, quando foi sepultado aqui, nem por que {link:sida}Sida{/link} visita sua tumba.]=],
		},
	},
})

Translate("ptBR", "direforge-hill", {
	title = "Monte Umbraforja",
	sections = {
		{
			title = "Resumo",
			text = [=[O Monte Umbraforja ergue-se a leste de {link:dun-modr}Dun Modr{/link}. É o principal acampamento dos {link:dark-iron-dwarves}Ferro Negro{/link} no {link:wetlands}Pantanal{/link}. Daqui seus escavadores cavam, seus sabotadores partem e seus demolidores levam a pólvora que derrubou a {link:thandol-span}Ponte Thandol{/link}. Seu senhor nestas terras é o bruxo {link:balgaras-the-foul}Balgaras, o Imundo{/link}, que raramente é visto nos combates. Os anões do acampamento de {link:longbraid-the-grim}Longbraid{/link} sabem que a guerra pelo norte será decidida neste monte.]=],
		},
	},
})

Translate("ptBR", "raptor-ridge", {
	title = "Serra dos Raptores",
	sections = {
		{
			title = "Resumo",
			text = [=[A Serra dos Raptores é uma plataforma alta e rochosa no nordeste do {link:wetlands}Pantanal{/link}. É o lar dos raptores navalhadentes, e uma grande matriarca de sua espécie domina a serra. Poucos caçadores a escalam de boa vontade. Os que o fazem vêm atrás dos dentes e dos ovos dos navalhadentes, e voltam com cicatrizes.]=],
		},
	},
})

Translate("ptBR", "bluegill-marsh", {
	title = "Pântano Peixeazul",
	sections = {
		{
			title = "Resumo",
			text = [=[O Pântano Peixeazul fica na costa ao norte do {link:menethil-harbor}Porto de Menethil{/link}. Os murlocs Peixeazul subiram das águas profundas e construíram seus casebres ao longo da margem. Atacam pescadores e mercadores na estrada, e quando o navio mercante {i}Blind Princess{/i} passou, arrastaram boa parte de sua carga para o mar. Um {link:murlocs}murloc{/link} chamado Gobbler lidera ataques a partir da enseada do rio e sempre escapa de volta para a segurança dos casebres.]=],
		},
	},
})

Translate("ptBR", "black-channel-marsh", {
	title = "Pântano do Canal Negro",
	sections = {
		{
			title = "Resumo",
			text = [=[O Pântano do Canal Negro é um labirinto de águas escuras e juncos no oeste do {link:wetlands}Pantanal{/link}, entre o {link:menethil-harbor}Porto de Menethil{/link} e a escavação da {link:explorers-league}Liga dos Exploradores{/link}. Seus canais são o refúgio dos crocoliscos gigantes que os curtidores de Menethil tanto prezam, e os raptores malhados das colinas descem até suas margens para caçar. O aprendiz do curtidor veio até aqui para esfolar crocoliscos, e os crocoliscos levaram sua perna.]=],
		},
	},
})

Translate("ptBR", "the-green-belt", {
	title = "Zona Verde",
	sections = {
		{
			title = "Resumo",
			text = [=[A Zona Verde é um longo vale de relva e água no leste do {link:wetlands}Pantanal{/link}, a leste do ponto em que a estrada se bifurca rumo a {link:dun-modr}Dun Modr{/link}. Dragonetes carmesins fazem ninhos ao longo dele. Ursos enlouquecidos por alguma doença vagam por suas encostas. {link:rethiel-the-greenwarden}O Guarda Verde{/link}, espírito do pântano, caminha aqui entre os crocoliscos, e os orcs das colinas nunca estão longe.]=],
		},
	},
})

Translate("ptBR", "the-lost-fleet", {
	title = "Frota Perdida",
	sections = {
		{
			title = "Resumo",
			text = [=[A Frota Perdida é o cemitério de navios na costa noroeste do {link:wetlands}Pantanal{/link}. Aqui a {link:third-fleet}Terceira Frota{/link} de {link:kul-tiras}Kul Tiraz{/link} queimou e afundou sob o fogo dos dragões vermelhos na {link:second-war}Segunda Guerra{/link}. Seus cascos ainda jazem nas águas rasas. Nem todas as tripulações encontraram descanso. Algo amaldiçoado foi escondido a bordo de um dos navios, e seu poder prende os marinheiros e fuzileiros afogados em seus conveses apodrecidos, e o capitão deles entre eles.]=],
		},
	},
})

Translate("ptBR", "thelgen-rock", {
	title = "Rocha de Thelgen",
	sections = {
		{
			title = "Resumo",
			text = [=[A Rocha de Thelgen é uma caverna nas colinas do sul do {link:wetlands}Pantanal{/link}, a sudeste da escavação de {link:prospector-whelgar}Whelgar{/link}. Aranhas a enchem, e seu veneno é tão forte que os alquimistas de Menethil precisam de suas glândulas intactas para fazer antídoto. Uma grande aranha chamada Leech Widow caça perto de sua entrada. O caminho que passa pela Rocha de Thelgen sobe para as terras altas onde fica o {link:excavation-site}Sítio de Escavação{/link}.]=],
		},
	},
})

Translate("ptBR", "the-drunken-dwarf", {
	title = "The Drunken Dwarf",
	sections = {
		{
			title = "Resumo",
			text = [=[The Drunken Dwarf é uma taberna aberta há pouco tempo no sul do {link:wetlands}Pantanal{/link}, perto da estrada que sai de {link:dun-algaz}Dun Algaz{/link}. É uma visão bem-vinda para os viajantes que atravessaram o desfiladeiro com orcs em seus calcanhares. Aurian Highgrove cuida do balcão. Os Firebrew, Bhalir e Agriel, cuidam da cozinha. Seu nome, "O Anão Bêbado", é uma promessa que a maioria de seus hóspedes cumpre de bom grado.]=],
		},
	},
})

Translate("ptBR", "captain-stoutfist", {
	title = "Capitão Stoutfist",
	subtitle = "Comandante da Bastilha Menethil",
	found = "A sala de guerra da Bastilha Menethil",
	hint = [=[Procure o capitão que planeja a defesa de Menethil na sala de guerra de sua fortaleza.]=],
	allegiance = "Reino de Altaforja",
	aliases = { "Stoutfist" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Capitão Stoutfist comanda o {link:menethil-harbor}Porto de Menethil{/link} em nome do {link:kingdom-of-ironforge}Reino de Altaforja{/link}. Da sala de guerra da Bastilha Menethil, ele vigia três inimigos ao mesmo tempo: os {link:dark-iron-dwarves}Ferro Negro{/link} no norte, os {link:dragonmaw-clan}Presa do Dragão{/link} nas colinas e os orcs que agora sufocam o desfiladeiro de {link:dun-algaz}Dun Algaz{/link}. Tem poucos soldados e menos reforços ainda. Convoca todo guerreiro que chega pelo desfiladeiro.]=],
		},
		{
			title = "Importância",
			text = [=[Stoutfist é o homem de quem depende toda a costa oeste. Se Menethil cair, a {link:alliance}Aliança{/link} perde seu porto no norte e a estrada entre {link:ironforge}Altaforja{/link} e o mar.]=],
		},
		{
			title = "Feitos",
			text = [=[• Recebe os relatórios de {link:valstag-ironjaw}Valstag Ironjaw{/link} sobre o avanço dos {link:dragonmaw-clan}Presa do Dragão{/link} em {link:dun-algaz}Dun Algaz{/link}.
• Envia guerreiros contra o {link:angerfang-encampment}Acampamento Presirada{/link} para tomar os estandartes de guerra dos orcs.
• Ordena que as catapultas dos Presa do Dragão sejam queimadas, e que o chefe deles morra.
• Quer as armas de {link:dragonmaw-retreat}Dragonmaw Retreat{/link} tomadas antes que possam armar novos soldados.]=],
		},
	},
	chapters = {
		{
			title = "A Cartada de Nek'rosh",
			hint = [=[Descubra o que os Presa do Dragão construíram em seu acampamento.]=],
			text = [=[Os guerreiros que atacaram Presirada voltaram com mais do que estandartes. Tinham visto catapultas. {link:chieftain-nek-rosh}Nek'rosh{/link} pretendia sitiar Menethil, e com {link:dun-algaz}Dun Algaz{/link} em mãos orcs, nenhuma ajuda chegaria ao porto a tempo. Stoutfist distribuiu isca de fogo e deu uma ordem simples: queimem as máquinas e depois cortem a fera pelo pescoço.]=],
		},
		{
			title = "A Estatueta do Rei",
			hint = "Leve a estatueta recuperada à fortaleza de Menethil.",
			text = [=[A estatueta de prata tomada dos murlocs tinha como destino a fortaleza dele. Stoutfist ficou orgulhoso de ter nas mãos um memorial do {link:terenas-menethil}Rei Terenas{/link}, cujo nome sua fortaleza leva, mas sabia bem o que era seu porto: um lugar calmo numa tempestade de inimigos. Temia o que os {link:dragonmaw-clan}Presa do Dragão{/link} fariam com algo assim, e a enviou a {link:stormwind-city}Ventobravo{/link} para que fosse guardada em segurança.]=],
		},
	},
	mentions = {
		{ text = "Apresente-se ao Capitão Stoutfist" },
		{ text = "Estandartes de Guerra" },
		{ text = "A Cartada de {link:chieftain-nek-rosh}Nek'rosh{/link}" },
		{ text = "Derrote {link:chieftain-nek-rosh}Nek'rosh{/link}" },
		{ text = "Devolva a Estatueta" },
		{ text = "Um Amigo da Família, para o Grão-lorde" },
		{ text = "Um Amigo da Família, para a Catedral" },
		{ text = "Desarmamento Forçado" },
	},
	bonds = {
		{ id = "valstag-ironjaw", name = "Valstag Ironjaw", note = "traz-lhe relatórios de Dun Algaz" },
		{ id = "chieftain-nek-rosh", name = "Chefe Nek'rosh", note = "inimigo" },
		{ id = "karl-boran", name = "Karl Boran", note = "enviou-lhe a estatueta" },
		{ id = "bolvar-fordragon", name = "Bolvar Fordragon", note = "o Grão-lorde a quem a confia" },
	},
})

Translate("ptBR", "valstag-ironjaw", {
	title = "Valstag Ironjaw",
	subtitle = "Oficial de Menethil",
	found = "Porto de Menethil, perto da fortaleza",
	hint = [=[Encontre o anão de Menethil que recebe os relatórios da estrada de Algaz.]=],
	allegiance = "Reino de Altaforja",
	aliases = { "Valstag" },
	sections = {
		{
			title = "Resumo",
			text = [=[Valstag Ironjaw recebe aqueles que abrem caminho à força por {link:dun-algaz}Dun Algaz{/link} até Menethil. Ele conhece bem os orcs. Os {link:dragonmaw-clan}Presa do Dragão{/link} sempre se mantiveram nas colinas, e ele não consegue explicar por que agora se lançaram sobre o desfiladeiro. Também conhece a história do chão sob suas botas. O porto foi primeiro um estaleiro {link:orcs}orc{/link}, construído com madeira e ferro roubados de Khaz Modan, e muito desse saque ainda está espalhado pelas docas.]=],
		},
		{
			title = "Feitos",
			text = [=[• Envia notícias dos combates de Algaz ao {link:captain-stoutfist}Capitão Stoutfist{/link}.
• Recolhe a velha madeira e o velho ferro orcs do porto para reforçar suas defesas.]=],
		},
	},
	mentions = {
		{ text = "A Travessia de Algaz" },
		{
			text = [=[Apresente-se ao {link:captain-stoutfist}Capitão Stoutfist{/link}]=],
		},
		{ text = "Espólios de Guerra" },
	},
	bonds = {
		{ id = "captain-stoutfist", name = "Capitão Stoutfist", note = "seu comandante" },
		{ id = "mountaineer-rockgar", name = "Montanhista Rockgar", note = "envia-lhe voluntários pelo desfiladeiro" },
	},
})

Translate("ptBR", "karl-boran", {
	title = "Karl Boran",
	subtitle = "Agente da Marinha Mercante",
	found = "As docas do Porto de Menethil",
	hint = [=[Fale com o homem nas docas que paga pela segurança dos mercadores.]=],
	allegiance = "Marinha Mercante",
	sections = {
		{
			title = "Resumo",
			text = [=[Karl Boran cuida dos mercadores que negociam pelo {link:menethil-harbor}Porto de Menethil{/link}. Os murlocs Peixeazul tornaram esse trabalho difícil. Eles atormentam a estrada da costa e atacam os navios, e quando investiram contra o navio mercante {i}Blind Princess{/i}, arrastaram boa parte de sua carga para o mar. A peça mais preciosa era uma estatueta de prata, um memorial do Rei {link:terenas-menethil}Terenas Menethil{/link}. Boran paga bem para tê-la de volta.]=],
		},
		{
			title = "Feitos",
			text = [=[• Põe a cabeça do {link:murlocs}murloc{/link} Gobbler e de seus parentes a prêmio.
• Envia gente para vasculhar os casebres dos murlocs em busca da carga perdida do {i}Blind Princess{/i}.]=],
		},
	},
	mentions = {
		{ text = "Garras das {link:blackfathom-deeps}Profundezas{/link}" },
		{ text = "Recuperando Mercadorias" },
		{ text = "Devolva a Estatueta" },
	},
	bonds = {
		{ id = "captain-stoutfist", name = "Capitão Stoutfist", note = "a estatueta era destinada à fortaleza dele" },
	},
})

Translate("ptBR", "first-mate-fitzsimmons", {
	title = "Imediato Fitzsimmons",
	subtitle = "Último Sobrevivente da Terceira Frota",
	found = "A Taberna Aguafunda, Porto de Menethil",
	hint = [=[Pague uma bebida ao marinheiro que afoga suas lembranças na Taberna Aguafunda.]=],
	allegiance = "Kul Tiraz (no passado)",
	aliases = { "Fitzsimmons" },
	sections = {
		{
			title = "Resumo",
			text = [=[Fitzsimmons era imediato do {i}Wave Mistress{/i}, um navio de linha da {link:third-fleet}Terceira Frota{/link} de {link:kul-tiras}Kul Tiraz{/link}. Na última viagem da frota, dragões vermelhos montados por orcs caíram sobre ela e a queimaram diante da costa do {link:wetlands}Pantanal{/link}. Só ele sobreviveu. Agora passa os dias na Taberna Aguafunda, cheirando mal e com sede, e as noites sonhando com seus irmãos afogados.]=],
		},
		{
			title = "Importância",
			text = [=[Fitzsimmons é a memória viva da {link:third-fleet}Frota Condenada{/link}. Só ele sabe que algo terrível foi escondido a bordo de um de seus navios, e que seu poder impede os mortos de descansar.]=],
		},
		{
			title = "Feitos",
			text = [=[• Conta a história da {link:third-fleet}Terceira Frota{/link} a quem lhe paga hidromel.
• Pede que seus irmãos amaldiçoados sejam libertados.
• Envia buscadores ao fantasma do {link:captain-halyndor}Capitão Halyndor{/link} atrás da chave do cofre do navio.
• Indica o caminho até o {link:rethiel-the-greenwarden}Guarda Verde{/link}, e avisa o buscador para não ir.]=],
		},
	},
	chapters = {
		{
			title = "A Frota Condenada",
			hint = [=[Solte a língua do velho marinheiro com uma caneca de hidromel.]=],
			text = [=[Com uma bebida nova na mão, Fitzsimmons conta tudo sem rodeios. A frota zarpou; os dragões vieram; os navios queimaram e afundaram. Ele não sabe por que sobreviveu. Amaldiçoa seu capitão por tê-los levado à perdição, e bebe a seus irmãos em seus túmulos de água.]=],
		},
		{
			title = "O Olho Amaldiçoado",
			hint = "Abra o cofre do Intrepid.",
			text = [=[O {link:captain-halyndor}Capitão Halyndor{/link} guardava a coisa trancada em seu cofre a bordo do {i}Intrepid{/i}. Quando o cofre foi aberto, continha um orbe enegrecido que pulsava com uma luz doentia: um Olho de Paleth, corrompido pela tristeza que havia testemunhado. Fitzsimmons não quis tocá-lo. Enviou-o ao sacerdote {link:glorin-steelbrow}Glorin Steelbrow{/link}.]=],
		},
	},
	mentions = {
		{ text = "{link:third-fleet}A Terceira Frota{/link}" },
		{ text = "A Tripulação Amaldiçoada" },
		{ text = "Quebrando a Maldição" },
		{ text = "{link:rethiel-the-greenwarden}O Guarda Verde{/link}" },
	},
	bonds = {
		{ id = "captain-halyndor", name = "Capitão Halyndor", note = "seu antigo capitão, a quem culpa" },
		{ id = "glorin-steelbrow", name = "Glorin Steelbrow", note = "recebeu o Olho" },
		{ id = "rethiel-the-greenwarden", name = "Rethiel, o Guarda Verde", note = "o espírito contra o qual adverte" },
	},
})

Translate("ptBR", "glorin-steelbrow", {
	title = "Glorin Steelbrow",
	subtitle = "Sacerdote de Menethil",
	found = "A Taberna Aguafunda, Porto de Menethil",
	hint = [=[Encontre o sacerdote anão que conhece os segredos da frota afundada.]=],
	allegiance = "Reino de Altaforja · Igreja da Luz Sagrada",
	aliases = { "Glorin" },
	sections = {
		{
			title = "Resumo",
			text = [=[Glorin Steelbrow é um sacerdote {link:dwarves}anão{/link} da {link:holy-light}Luz Sagrada{/link} que vive no {link:menethil-harbor}Porto de Menethil{/link}. Ele conhece os destroços da {link:third-fleet}Terceira Frota{/link} melhor que a maioria. Um navio que navegava com ela, o {i}Flying Osprey{/i}, levava uma carga de ferro forjado pela Luz, um metal que golpeia com força sagrada. Glorin sabe dizer onde ele está e quem sabe trabalhá-lo. Mas quando o Olho Amaldiçoado de Paleth chegou a suas mãos, ele não conseguiu purificá-lo. Os Olhos foram feitos por sacerdotes humanos, e só um mestre humano poderia curar um deles.]=],
		},
		{
			title = "Feitos",
			text = [=[• Envia buscadores aos destroços do {i}Flying Osprey{/i} atrás de ferro forjado pela Luz.
• Envia o Olho Amaldiçoado de Paleth ao {link:archbishop-benedictus}Arcebispo Benedictus{/link}, em {link:stormwind-city}Ventobravo{/link}.]=],
		},
	},
	mentions = {
		{ text = "A {link:third-fleet}Frota Condenada{/link}" },
		{ text = "Ferro Forjado pela Luz" },
		{ text = "Os Lingotes Perdidos" },
		{ text = "Braço Abençoado" },
		{ text = "O Olho de Paleth" },
		{ text = "Purificando o Olho" },
	},
	bonds = {
		{ id = "first-mate-fitzsimmons", name = "Imediato Fitzsimmons", note = "um bêbado a quem não paga bebidas" },
		{ id = "archbishop-benedictus", name = "Arcebispo Benedictus", note = "pode purificar o Olho" },
	},
})

Translate("ptBR", "innkeeper-helbrek", {
	title = "Estalajadeiro Helbrek",
	subtitle = "Dono da Taberna Aguafunda",
	found = "A Taberna Aguafunda, Porto de Menethil",
	hint = "Alugue um quarto na Taberna Aguafunda.",
	allegiance = "Reino de Altaforja",
	aliases = { "Helbrek" },
	sections = {
		{
			title = "Resumo",
			text = [=[Helbrek cuida da Taberna Aguafunda, a casa mais movimentada do {link:menethil-harbor}Porto de Menethil{/link}. Todos que desembarcam no {link:wetlands}Pantanal{/link} passam sob seu teto cedo ou tarde: marinheiros vindos dos navios, soldados vindos da estrada de Algaz, estudiosos da {link:explorers-league}Liga dos Exploradores{/link} à espera de escolta até sua escavação. {link:mikhail}Mikhail{/link} serve as bebidas em seu balcão. Um sobrevivente bêbado da {link:third-fleet}Terceira Frota{/link} ocupa suas mesas, e nem todo hóspede é o que parece.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Pouco se escreveu sobre o próprio Helbrek. Sua taberna diz mais sobre o porto do que ele.]=],
		},
	},
	bonds = {
		{ id = "mikhail", name = "Mikhail", note = "seu taberneiro" },
		{ id = "first-mate-fitzsimmons", name = "Imediato Fitzsimmons", note = "um freguês habitual" },
	},
})

Translate("ptBR", "mikhail", {
	title = "Mikhail",
	subtitle = "Taberneiro da Taberna Aguafunda",
	found = "O balcão da Taberna Aguafunda",
	hint = [=[Mencione um velho amigo de Ventobravo ao taberneiro da Taberna Aguafunda.]=],
	allegiance = "Taberna Aguafunda (no passado, agente de Ventobravo)",
	sections = {
		{
			title = "Resumo",
			text = [=[Mikhail serve bebidas na Taberna Aguafunda. Alguns anos atrás, deixou {link:stormwind-city}Ventobravo{/link} e o trabalho sombrio que fazia lá, e se estabeleceu à beira-mar. Ainda é amigo de {link:elling-trias}Elling Trias{/link}, e para quem chega em nome de Elling, sua hospitalidade não tem limites. Ele admite, um pouco envergonhado, que às vezes sente falta da antiga emoção.]=],
		},
	},
	chapters = {
		{
			title = "O Homem Junto à Porta",
			hint = "Ajude Mikhail com o estranho que escuta com atenção demais.",
			text = [=[Um freguês junto à porta vinha escutando com atenção demais. Era {link:tapoke-slim-jahn}Tapoke Jahn{/link}, chamado Slim, e uma vez pego, falou. Tinha aceitado moedas dos {link:defias-brotherhood}Défias{/link} para pôr o homem deles a bordo de um navio real no porto. Mikhail jurou que até um ladino precisa guardar alguma honra, e mandou avisar Elling na mesma hora.]=],
		},
	},
	mentions = {
		{ text = "O Diplomata Desaparecido" },
		{ text = "O Diplomata Desaparecido" },
		{ text = "O Diplomata Desaparecido" },
		{
			text = [=[O Diplomata Desaparecido, para {link:theramore-isle}Theramore{/link}]=],
		},
	},
	bonds = {
		{ id = "elling-trias", name = "Elling Trias", note = "seu velho amigo em Ventobravo" },
		{ id = "tapoke-slim-jahn", name = "Tapoke \"Slim\" Jahn", note = "o traidor que ele desmascarou" },
		{ id = "innkeeper-helbrek", name = "Estalajadeiro Helbrek", note = "seu patrão" },
	},
})

Translate("ptBR", "tapoke-slim-jahn", {
	title = "Tapoke \"Slim\" Jahn",
	subtitle = "Um Traidor na Taberna",
	found = "A Taberna Aguafunda, Porto de Menethil",
	hint = [=[Observe o freguês que escuta com atenção demais na Taberna Aguafunda.]=],
	allegiance = "Irmandade Défias (por dinheiro)",
	aliases = { "Slim", "Tapoke Jahn" },
	sections = {
		{
			title = "Resumo",
			text = [=[Tapoke Jahn, a quem o submundo chama de Slim, bebe na Taberna Aguafunda e mantém os ouvidos abertos. Foi pago pela {link:defias-brotherhood}Irmandade Défias{/link} para uma única tarefa no {link:menethil-harbor}Porto de Menethil{/link}, e a cumpriu. Quando soube que estranhos perguntavam por ele, tentou escapulir pela porta.]=],
		},
	},
	chapters = {
		{
			title = "O Que Slim Sabia",
			hint = "Detenha Slim antes que ele fuja da taberna.",
			text = [=[Slim não fora pago o bastante para morrer pelos {link:defias-brotherhood}Défias{/link}, e disse isso. O prisioneiro que eles haviam capturado não era diplomata nenhum. Era o rei de {link:stormwind-city}Ventobravo{/link}, navegando em segredo para {link:theramore-isle}Theramore{/link}. A parte de Slim fora pôr um homem, chamado {link:private-hendel}Hendel{/link}, a bordo do navio do rei no porto. Ele acreditava que os Défias trabalhavam para alguém maior do que eles.]=],
		},
	},
	mentions = {
		{ text = "O Diplomata Desaparecido" },
		{ text = "O Diplomata Desaparecido" },
	},
	bonds = {
		{ id = "mikhail", name = "Mikhail", note = "o desmascarou" },
		{ id = "varian-wrynn", name = "Varian Wrynn", note = "o rei que ele ajudou a trair" },
	},
})

Translate("ptBR", "sida", {
	title = "Sida",
	subtitle = "Uma Mulher de Menethil",
	found = "Porto de Menethil, perto da loja de mercadorias gerais",
	hint = [=[Fale com a mulher de Menethil que perdeu a bolsa para uma gosma.]=],
	allegiance = "Porto de Menethil",
	sections = {
		{
			title = "Resumo",
			text = [=[Sida vive no {link:menethil-harbor}Porto de Menethil{/link}. Uma vez por semana, ela caminha até a {link:ironbeard-s-tomb}Tumba dos Barbaférreos{/link}, perto de {link:dun-modr}Dun Modr{/link}, atravessando uma terra em guerra. Em sua última visita, as gosmas da tumba vieram atrás dela. Em pânico, ela atirou a bolsa em uma delas, e a gosma a engoliu inteira. Ela escapou, mas a bolsa guardava algo de que ela precisava muito.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Sida não diz por que visita a tumba, nem o que guardava na bolsa. O curtidor {link:james-halloran}James Halloran{/link} certa vez pensou em mandar a esposa falar com ela, embora não tenha dito por quê.]=],
		},
	},
	mentions = {
		{ text = "Cavando na Gosma" },
		{ text = "Entrega Diária" },
	},
	bonds = {
		{ id = "james-halloran", name = "James Halloran", note = "um vizinho que fala dela" },
	},
})

