		{ text = "Entrega de Caixote Carmesim" },
	},
	bonds = {
		{ id = "howin-kindfeather", name = "Howin Kindfeather", note = "encomendou suas escamas de dragonete" },
		{ id = "sida", name = "Sida", note = "uma vizinha" },
	},
})

Translate("ptBR", "sylessa-duskwhisper", {
	title = "Sylessa Duskwhisper",
	subtitle = "Buscadora da Flor",
	found = "Porto de Menethil",
	hint = [=[Fale com a elfa noturna que cruzou o mar até Menethil em busca de uma flor.]=],
	allegiance = "Elfos noturnos de Teldrassil",
	sections = {
		{
			title = "Resumo",
			text = [=[Sylessa Duskwhisper é uma {link:night-elves}elfa noturna{/link} que veio ao {link:menethil-harbor}Porto de Menethil{/link} de {link:auberdine}Auberdine{/link} e da grande árvore {link:teldrassil}Teldrassil{/link}. Ela busca uma única flor. Entre a carga do {i}Flying Osprey{/i}, perdido com a {link:third-fleet}Terceira Frota{/link} diante desta costa, estava Nord'el, a Flor dos Céus. Ela floresceu sob a lua cheia no pico do {link:mount-hyjal}Monte Hyjal{/link}, o antigo lar de seu povo, e sua perda ainda o entristece.]=],
		},
		{
			title = "Feitos",
			text = [=[• Busca ajuda para recuperar Nord'el dos destroços do {i}Flying Osprey{/i}, onde agora vivem saqueadores murlocs.]=],
		},
	},
	mentions = {
		{ text = "Flor dos Céus" },
	},
	bonds = {
		{ id = "glorin-steelbrow", name = "Glorin Steelbrow", note = "conhece os mesmos destroços" },
