Translate("ptBR", "prospector-whelgar", {
	title = "Prospector Whelgar",
	subtitle = "Líder da Escavação do Pantanal",
	found = "O penhasco acima do Sítio de Escavação de Whelgar",
	hint = [=[Procure o velho prospector que lidera a escavação da Liga dos Exploradores no Pantanal.]=],
	allegiance = "Liga dos Exploradores",
	aliases = { "Whelgar" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Prospector Whelgar lidera a escavação da {link:explorers-league}Liga dos Exploradores{/link} que leva seu nome. Ele é velho, velho demais, diz, para descer entre as feras que tomaram seu acampamento. Mas sua mente é afiada. Pouco antes de os raptores chegarem, ele desenterrou uma grande tábua, a {link:goaz-stone}Pedra de Goaz{/link}, gravada na escrita dos titãs e quebrada em quatro pontos. Ele acredita que os pedaços que faltam guardam a chave de um mistério maior que qualquer outro que a Liga já encontrou.]=],
		},
		{
			title = "Importância",
			text = [=[A tábua de Whelgar fala de um plano divino e de uma profecia condenada, e de Deuses Antigos acorrentados sob a terra. Poucos achados da Liga tocaram em coisas mais antigas ou mais sombrias.]=],
		},
		{
			title = "Feitos",
			text = [=[• Guarda o fóssil original que o {link:archaeologist-flagongut}Arqueólogo Flagongut{/link} deseja estudar.
• Sobreviveu ao ataque dos raptores à sua escavação com {link:merrin-rockweaver}Merrin Rockweaver{/link} e {link:ormer-ironbraid}Ormer Ironbraid{/link}.
• Trabalha para traduzir a escrita titânica da {link:goaz-stone}Pedra de Goaz{/link}.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Nenhuma crônica registra a vida de Whelgar antes da escavação, nem há quanto tempo ele serve à Liga.]=],
		},
	},
	chapters = {
		{
			title = "A Pedra de Goaz",
			hint = "Recupere os fragmentos perdidos da tábua do prospector.",
			text = [=[Os fragmentos se chamavam Ados, Modr, Golm e Neru, e estavam espalhados pelas ruínas da escavação, entre relíquias antigas e terra solta. Quando o último foi encaixado, Whelgar se debruçou sobre a pedra e começou a ler. Novas palavras lhe vieram de imediato, e ele as disse em voz alta: Deuses Antigos, acorrentados sob a terra. Não disse o que temia que significassem. Disse apenas que era o começo de algo grandioso.]=],
		},
	},
	mentions = {
		{ text = "Desvendando o Passado" },
		{ text = "O Prospector Distraído" },
		{ text = "Em Busca da Equipe de Escavação" },
	},
	bonds = {
		{ id = "merrin-rockweaver", name = "Merrin Rockweaver", note = "uma escavadora de sua equipe" },
		{ id = "ormer-ironbraid", name = "Ormer Ironbraid", note = "salvou sua vida" },
		{ id = "archaeologist-flagongut", name = "Arqueólogo Flagongut", note = "quer seu fóssil" },
	},
})

Translate("ptBR", "longbraid-the-grim", {
	title = "Longbraid, o Severo",
	subtitle = "Comandante do Regimento de Dun Modr",
	found = "O acampamento diante de Dun Modr",
	hint = [=[Procure o comandante anão que mantém o acampamento diante da caída Dun Modr.]=],
	allegiance = "Reino de Altaforja",
	aliases = { "Longbraid" },
	sections = {
		{
			title = "Resumo",
			text = [=[Longbraid, o Severo, liderava o regimento de {link:ironforge}Altaforja{/link} que guardava {link:dun-modr}Dun Modr{/link} e a {link:thandol-span}Ponte Thandol{/link}. Perdeu as duas. Os {link:dark-iron-dwarves}Ferro Negro{/link} explodiram a ponte oeste numa emboscada, e seu irmão morreu com ela. Antes que o regimento pudesse se recuperar, eles caíram sobre a cidade. Longbraid tocou a trompa de retirada, e agora mantém um pequeno acampamento do lado de fora das muralhas com os poucos que sobreviveram.]=],
		},
		{
			title = "Importância",
			text = [=[Longbraid é a dor e a teimosia de Khaz Modan num único {link:dwarves}anão{/link}. Não tem reserva, nem aliados de sobra, nem cidade, e ainda assim não abandonou a estrada do norte.]=],
		},
		{
			title = "Feitos",
			text = [=[• Tocou a retirada quando {link:dun-modr}Dun Modr{/link} caiu, e salvou o que restava de seu regimento.
• Mandou um cavaleiro para o sul, a Menethil, com o ferido {link:harlo-barnaby}Harlo Barnaby{/link}.
• Caça o bruxo que lidera os {link:dark-iron-dwarves}Ferro Negro{/link} no {link:wetlands}Pantanal{/link}.
• Enviou um batedor, o Velho Rustlocke, à ponte leste, e o batedor nunca voltou.]=],
		},
	},
	chapters = {
		{
			title = "A Queda de Dun Modr",
			hint = "Traga notícias do soldado ferido em Menethil.",
			text = [=[Longbraid soube que o jovem {link:harlo-barnaby}Harlo{/link} sobrevivera, e por um momento a notícia lhe deu esperança. Então contou o resto sem rodeios. {link:dun-modr}Dun Modr{/link} estava perdida. O regimento que a guardava era agora apenas uma sombra de si mesmo.]=],
		},
		{
			title = "Uma Tarefa Sombria",
			hint = "Cace o bruxo que lidera os Ferro Negro.",
			text = [=[Os {link:dark-iron-dwarves}Ferro Negro{/link} do {link:wetlands}Pantanal{/link} eram liderados por {link:balgaras-the-foul}Balgaras, o Imundo{/link}, um bruxo que mandava outros morrerem e se mantinha fora de alcance. Quando sua orelha foi posta diante de Longbraid, o comandante não sentiu alegria. Os mortos não voltariam. Mas os vivos talvez dormissem, e o resto dos Ferro Negro teria de ser expulso antes que viesse um novo senhor.]=],
		},
	},
	mentions = {
		{ text = "A Queda de {link:dun-modr}Dun Modr{/link}" },
		{ text = "Uma Tarefa Sombria" },
		{ text = "A Fúria Vem de Longe, seu irmão vingado" },
		{ text = "Em Busca da Equipe de Escavação" },
	},
	bonds = {
		{ id = "motley-garmason", name = "Motley Garmason", note = "preso pela honra a ficar a seu lado" },
		{ id = "rhag-garmason", name = "Rhag Garmason", note = "seu oficial" },
		{ id = "harlo-barnaby", name = "Harlo Barnaby", note = "um soldado que ele mandou para a segurança" },
		{ id = "balgaras-the-foul", name = "Balgaras, o Imundo", note = "inimigo" },
		{ id = "kam-deepfury", name = "Kam Deepfury", note = "planejou a morte de seu irmão" },
	},
})

