	sections = {
		{
			title = "Resumo",
			text = [=[O Guarda Verde é um espírito do pântano vivo. Os marinheiros de Menethil falam dele como de uma fera que parte homens ao meio. A verdade é mais estranha. Ele tem muitos nomes e responde a poucos, mas aqueles em quem confia podem chamá-lo de Rethiel. Sente o {link:wetlands}Pantanal{/link} como seu próprio corpo. Diz que a terra chora por feridas que supuram, e que os povos do mundo já puseram sua fé à prova antes.]=],
