	},
})

Translate("ptBR", "howin-kindfeather", {
	title = "Howin Kindfeather",
	subtitle = "Cavaleiro de Grifo do Pantanal",
	found = [=[Um acampamento à beira da estrada, a leste do Sítio de Escavação de Whelgar]=],
