	},
	mentions = {
		{ text = "Entrega de Caixote Carmesim" },
		{ text = "Agulhas de Navalhadente" },
		{ text = "Tempos Difíceis" },
	},
	bonds = {
		{ id = "james-halloran", name = "James Halloran", note = "vendeu-lhe as escamas" },
	},
})

