Translate("ptBR", "chieftain-nek-rosh", {
	title = "Chefe Nek'rosh",
	subtitle = "Chefe dos Presa do Dragão",
	found = "Acampamento Presirada",
	hint = [=[Enfrente o chefe que lidera os Presa do Dragão de seu acampamento nas colinas do leste.]=],
	allegiance = "Clã Presa do Dragão",
	aliases = { "Nek'rosh" },
	sections = {
		{
			title = "Resumo",
			text = [=[Nek'rosh é o chefe do {link:dragonmaw-clan}clã Presa do Dragão{/link} no {link:wetlands}Pantanal{/link}. É filho de Nekros, que liderou o clã nos anos em que ele mantinha os dragões vermelhos cativos. Nekros dobrou os dragões à sua vontade com uma magia poderosa. Quando a magia falhou, os dragões se voltaram contra seus senhores, e Nekros foi morto. Seu filho jurou vingança contra os dragões que o mataram.]=],
		},
		{
			title = "Importância",
			text = [=[Sob Nek'rosh, um clã destroçado voltou a ser um exército. Os {link:dragonmaw-clan}Presa do Dragão{/link} avançaram sobre {link:dun-algaz}Dun Algaz{/link}, construíram máquinas de cerco e voltaram os olhos para o {link:menethil-harbor}Porto de Menethil{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[• Reuniu os {link:dragonmaw-clan}Presa do Dragão{/link} dispersos no {link:angerfang-encampment}Acampamento Presirada{/link}.
• Lançou seus guerreiros sobre {link:dun-algaz}Dun Algaz{/link}, cortando a estrada entre Menethil e {link:loch-modan}Loch Modan{/link}.
• Construiu catapultas para sitiar o {link:menethil-harbor}Porto de Menethil{/link}.]=],
		},
		{
			title = "Sem Registro",
			text = [=[As crônicas da {link:second-war}Segunda Guerra{/link} falam dos {link:dragonmaw-clan}Presa do Dragão{/link} que mantiveram a Rainha {link:the-drag}Drag{/link}ão em {link:grim-batol}Grim Batol{/link}. Que papel o próprio Nek'rosh teve naqueles anos, elas não dizem.]=],
		},
	},
	chapters = {
		{
			title = "O Filho de Nekros",
			hint = [=[Leve os estandartes de guerra dos Presa do Dragão ao capitão na Bastilha Menethil.]=],
			text = [=[Quando os estandartes foram postos diante dele, o {link:captain-stoutfist}Capitão Stoutfist{/link} contou o que os anões sabiam de seu inimigo. Os {link:dragonmaw-clan}Presa do Dragão{/link} já não eram o que tinham sido quando montavam dragões. Seu chefe era filho do {link:orcs}orc{/link} que outrora escravizara a revoada vermelha, e não havia esquecido como seu pai morreu.]=],
		},
		{
			title = "Derrote Nek'rosh",
			hint = "Queime as catapultas e abata o chefe.",
			text = [=[As catapultas queimaram primeiro, e Menethil ficou a salvo delas. Então Nek'rosh caiu em seu próprio acampamento. {link:captain-stoutfist}Stoutfist{/link} julgou o golpe decisivo, um golpe do qual o clã talvez nunca se recuperasse.]=],
		},
	},
	mentions = {
		{ text = "Estandartes de Guerra" },
		{ text = "A Cartada de Nek'rosh" },
		{ text = "Derrote Nek'rosh" },
	},
	bonds = {
		{ id = "captain-stoutfist", name = "Capitão Stoutfist", note = "inimigo" },
		{ id = "ma-ruk-wyrmscale", name = "Ma'ruk Wyrmscale", note = "seu senhor da guerra em Dun Algaz" },
		{ id = "alexstrasza", name = "Alexstrasza", note = "rainha dos dragões que seu pai escravizou" },
	},
})

Translate("ptBR", "ma-ruk-wyrmscale", {
	title = "Ma'ruk Wyrmscale",
	subtitle = "Senhor da Guerra Presa do Dragão",
	found = "Dun Algaz",
	hint = [=[Enfrente o senhor da guerra Presa do Dragão que domina o desfiladeiro de Dun Algaz.]=],
	allegiance = "Clã Presa do Dragão",
	aliases = { "Ma'ruk" },
	sections = {
		{
			title = "Resumo",
			text = [=[Ma'ruk Wyrmscale é um senhor da guerra do {link:dragonmaw-clan}clã Presa do Dragão{/link}. Lidera os orcs que desceram ao desfiladeiro de {link:dun-algaz}Dun Algaz{/link}, onde emboscam todo viajante entre {link:loch-modan}Loch Modan{/link} e o {link:wetlands}Pantanal{/link}. Enquanto ele dominar o desfiladeiro, nenhum reforço chega ao {link:menethil-harbor}Porto de Menethil{/link} por terra.]=],
		},
		{
