Translate("ptBR", "dragonmaw-clan", {
	title = "Clã Presa do Dragão",
	aliases = { "clã Presa do Dragão", "orcs Presa do Dragão", "Presa do Dragão" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Presa do Dragão são um clã de {link:orcs}orcs{/link} da antiga {link:horde}Horda{/link}. Na {link:second-war}Segunda Guerra{/link}, fizeram o que nenhum outro clã conseguiu: tornaram os dragões vermelhos seus servos. De sua fortaleza em {link:grim-batol}Grim Batol{/link}, mantiveram {link:alexstrasza}Alexstrasza{/link}, a Rainha {link:the-drag}Drag{/link}ão, cativa pelo poder de um artefato forjado por {link:deathwing}Asa da Morte{/link}, e criaram seus filhotes como montarias de guerra. Dragões vermelhos montados por orcs Presa do Dragão queimaram os navios da {link:alliance}Aliança{/link} no mar.]=],
		},
		{
			title = "A Queda",
			text = [=[A magia que prendia os dragões falhou. A revoada vermelha se voltou contra o clã e o caçou sem piedade. Nekros, que liderava os Presa do Dragão, foi morto, e o clã foi quase destruído. Os poucos que sobreviveram fugiram de {link:grim-batol}Grim Batol{/link} e se esconderam nas montanhas a leste da estrada do {link:wetlands}Pantanal{/link}.]=],
		},
		{
			title = "Nestes Dias",
			text = [=[Os Presa do Dragão voltaram a ficar fortes sob o {link:chieftain-nek-rosh}Chefe Nek'rosh{/link}, filho de Nekros. Do {link:angerfang-encampment}Acampamento Presirada{/link} e do escondido {link:dragonmaw-retreat}Dragonmaw Retreat{/link}, eles atacam para o oeste, e tomaram o desfiladeiro de {link:dun-algaz}Dun Algaz{/link}. Constroem catapultas, juntam armas e, dizem os sussurros, ainda sonham com dragões. Os anões de Menethil os chamam de ferozes, mas sabem que o clã sem seus dragões é uma ameaça menor que o clã que outrora escureceu o céu.]=],
		},
	},
})

Translate("ptBR", "third-fleet", {
	title = "Terceira Frota",
	aliases = { "A Terceira Frota", "a Frota Condenada", "Frota Condenada" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Terceira Frota de {link:kul-tiras}Kul Tiraz{/link} navegou na {link:second-war}Segunda Guerra{/link}, a última grande guerra contra a {link:horde}Horda{/link}. Seus navios vieram das costas de {link:lordaeron}Lordaeron{/link}, e pelo menos uma embarcação que não era sua juntou-se a ela em busca de proteção: o {i}Flying Osprey{/i}, que levava uma carga de ferro forjado pela Luz. Diante da costa do {link:wetlands}Pantanal{/link}, orcs montados em dragões vermelhos caíram sobre a frota. Os navios queimaram e afundaram, e os destroços ainda jazem ao longo da costa noroeste, no lugar chamado {link:the-lost-fleet}Frota Perdida{/link}.]=],
		},
		{
			title = "A Maldição",
			text = [=[Algo foi escondido a bordo do {i}Intrepid{/i}: um Olho de Paleth amaldiçoado, trancado no cofre do capitão. Os Olhos foram feitos por sacerdotes humanos para brilhar com luz sagrada, mas este havia testemunhado tristeza demais. Seu poder prende as tripulações afogadas em seus cascos apodrecidos. Só um homem da frota ainda vive, o imediato {link:first-mate-fitzsimmons}Fitzsimmons{/link}, e ele bebe em Menethil para não sonhar com eles.]=],
		},
		{
			title = "A Carga",
			text = [=[Os murlocs da costa saquearam o {i}Flying Osprey{/i}. Seus lingotes forjados pela Luz são prezados por aqueles que combatem os mortos-vivos. Uma elfa noturna de {link:teldrassil}Teldrassil{/link}, {link:sylessa-duskwhisper}Sylessa Duskwhisper{/link}, diz que o navio também levava Nord'el, uma flor do {link:mount-hyjal}Monte Hyjal{/link}.]=],
		},
	},
})

Translate("ptBR", "goaz-stone", {
	title = "Pedra de Goaz",
	aliases = { "A Pedra de Goaz" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Pedra de Goaz é uma grande tábua desenterrada pelo {link:prospector-whelgar}Prospector Whelgar{/link} em sua escavação no {link:wetlands}Pantanal{/link}, pouco antes de os raptores a invadirem. Ela é gravada na escrita dos titãs. Quando foi encontrada, estava quebrada em quatro pontos, e os pedaços perdidos traziam os nomes Ados, Modr, Golm e Neru. Mesmo em parte, a tábua falava de um plano divino e de uma profecia condenada.]=],
		},
		{
			title = "A Leitura",
			text = [=[Quando os quatro fragmentos foram restaurados, {link:prospector-whelgar}Whelgar{/link} começou o lento trabalho da tradução. As primeiras palavras novas que leu falavam de Deuses Antigos, acorrentados sob a terra. A {link:explorers-league}Liga dos Exploradores{/link} já encontrou entalhes titânicos antes, mas raramente algum que falasse tão claramente do que jaz lá embaixo.]=],
		},
		{
			title = "Os Dias Atuais",
			text = [=[{link:prospector-whelgar}Whelgar{/link} não terminou sua leitura. Acima de sua escavação, nas colinas, uma névoa começou a descer das montanhas e construtos dos titãs voltaram a caminhar. Se a pedra e o despertar das terras altas estão ligados, a Liga ainda não sabe.]=],
		},
	},
})
